// Middleware factory function
const restrictTo = (...roles) => {
  return (req, res, next) => {
    // req.user was attached by the JWT middleware previously
    if (!roles.includes(req.user.role)) {
      return res.status(403).json({
        error: 'You do not have permission to perform this action'
      });
    }
    next();
  };
};

// Only admins or lead-guides can delete tours
app.delete('/tours/:id', protect, restrictTo('admin', 'lead-guide'), deleteTour);
